(()=>{
 const root=document.getElementById('project-understanding');
 const buttons=[...root.querySelectorAll('[data-view]')];
 const panels=[...root.querySelectorAll('[data-panel]')];
 function select(view,focus){
  panels.forEach(panel=>panel.hidden=panel.dataset.panel!==view);
  buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));
  if(focus)root.querySelector('[data-panel="'+view+'"] h2').focus();
 }
 buttons.forEach(button=>button.addEventListener('click',()=>select(button.dataset.view,true)));
 const query=root.querySelector('#query');const files=[...root.querySelectorAll('[data-path]')];
 function lookup(){const value=query.value.trim().toLowerCase();let count=0;
  files.forEach(file=>{file.hidden=!file.dataset.path.includes(value);if(!file.hidden)count++});
  root.querySelector('#lookup-result').textContent=count?count+' 个匹配文件，共 '+files.length+' 个': '没有匹配文件。清空查找可恢复完整清单。';
 }
 query.addEventListener('input',lookup);
 root.querySelector('#clear').addEventListener('click',()=>{query.value='';lookup();query.focus()});
 select('overview',false);root.querySelector('nav').hidden=false;root.querySelector('#lookup').hidden=false;
 root.dataset.ready='true';
})();
"}
